 Throwable error=failure.getAndSet(null);if(error!=null)throw new IllegalStateException("Block mesh could not load",error);var next=pending.getAndSet(null);if(next!=null){upload(next);message="";readyFrames=0;}if(!building.get()&&needsMesh())requestMesh();glfwGetFramebufferSize(window,width,height);if(width[0]>0&&height[0]>0){draw(width[0],height[0]);glfwSwapBuffers(window);if(patch!=null||wholeBlocks!=null)readyFrames++;}
